use serde::{Deserialize, Serialize};

use tracing::instrument;

use self::{outputs::FlakeOutputs, schema::FlakeSchema, system::System, url::FlakeUrl};

use crate::command::NixCmdError;

/// All the information about a Nix flake
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Flake {
    /// The flake url which this struct represents
    pub url: FlakeUrl,
    /// `nix flake show` output
    pub output: FlakeOutputs,
    /// Flake output schema (typed version of [FlakeOutputs])
    pub schema: FlakeSchema,
    // TODO: Add `nix flake metadata` info.
}

impl Flake {
    /// Get [Flake] info for the given flake url

    #[instrument(name = "flake", skip(nix_cmd))]
    pub async fn from_nix(
        nix_cmd: &crate::command::NixCmd,
        url: FlakeUrl,
    ) -> Result<Flake, NixCmdError> {
        use crate::config::NixConfig;

        // TODO: Can we cache this?
        let nix_config = NixConfig::from_nix(nix_cmd).await?;
        let system = nix_config.system.value;
        let output = FlakeOutputs::from_nix(nix_cmd, &url).await?;
        let schema = FlakeSchema::from(&output, &system);
        Ok(Flake {
            url,
            output: output.clone(),
            schema,
        })
    }
}

//! Nix flake outputs

use serde::{Deserialize, Serialize};
use std::{
    collections::{btree_map::Entry, BTreeMap},
    fmt::Display,
};

/// Represents the "outputs" of a flake
///
/// This structure is currently produced by `nix flake show`, thus to parse it we must toggle serde untagged.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum FlakeOutputs {
    Val(Val),
    Attrset(BTreeMap<String, FlakeOutputs>),
}

impl FlakeOutputs {
    /// Run `nix flake show` on the given flake url
    pub async fn from_nix(
        nix_cmd: &crate::command::NixCmd,
        flake_url: &super::url::FlakeUrl,
    ) -> Result<Self, crate::command::NixCmdError> {
        let v = FlakeOutputsUntagged::from_nix(nix_cmd, flake_url).await?;
        Ok(v.into_flake_outputs())
    }

    /// Get the non-attrset value
    pub fn as_leaf(&self) -> Option<&Val> {
        match self {
            Self::Val(v) => Some(v),
            _ => None,
        }
    }

    /// Ensure the value is an attrset, and get it
    pub fn as_attrset(&self) -> Option<&BTreeMap<String, FlakeOutputs>> {
        match self {
            Self::Attrset(v) => Some(v),
            _ => None,
        }
    }

    /// Lookup the given path, returning the value, while removing it from the tree.
    ///
    /// # Example
    /// ```no_run
    /// let tree : &nix_rs::flake::outputs::FlakeOutputs = todo!();
    /// let val = tree.pop(&["packages", "aarch64-darwin", "default"]);
    /// ```
    pub fn pop(&mut self, path: &[&str]) -> Option<Self> {
        let mut curr = self;
        let mut path = path.iter().peekable();
        while let Some(part) = path.next() {
            let Self::Attrset(v) = curr else {
                return None;
            };
            let Entry::Occupied(entry) = v.entry(part.to_string()) else {
                return None;
            };
            if path.peek().is_none() {
                return Some(entry.remove());
            } else {
                curr = entry.into_mut();
            }
        }
        None
    }
}

/// The metadata of a flake output value which is of non-attrset [Type]
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Val {
    #[serde(rename = "type")]
    pub type_: Type,
    pub name: Option<String>,
    pub description: Option<String>,
}

/// The type of a flake output [Val]
///
/// [Nix source ref](https://github.com/NixOS/nix/blob/2.14.1/src/nix/flake.cc#L1105)
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum Type {
    NixosModule,
    Derivation,
    App,
    Template,
    #[serde(other)]
    Unknown,
}

impl Type {
    /// Get the icon for this type
    pub fn to_icon(&self) -> &'static str {
        match self {
            Self::NixosModule => "❄️",
            Self::Derivation => "📦",
            Self::App => "📱",
            Self::Template => "🏗️",
            Self::Unknown => "❓",
        }
    }
}

impl Display for Type {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&format!("{:?}", self))
    }
}

/// This type is identical to [FlakeOutputs] except for the serde untagged attribute, which enables parsing the JSON output of `nix flake show`.
///
/// This separation exists to workaround https://github.com/DioxusLabs/dioxus-std/issues/20
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(untagged)]
enum FlakeOutputsUntagged {
    UVal(Val),
    UAttrset(BTreeMap<String, FlakeOutputsUntagged>),
}

impl FlakeOutputsUntagged {
    /// Run `nix flake show` on the given flake url
    #[tracing::instrument(name = "flake-show")]
    async fn from_nix(
        nix_cmd: &crate::command::NixCmd,
        flake_url: &super::url::FlakeUrl,
    ) -> Result<Self, crate::command::NixCmdError> {
        let v = nix_cmd
            .run_with_args_expecting_json(&[
                "flake",
                "show",
                "--legacy", // for showing nixpkgs legacyPackages
                "--allow-import-from-derivation",
                "--json",
                &flake_url.to_string(),
            ])
            .await?;
        Ok(v)
    }

    /// Convert to [FlakeOutputs]
    fn into_flake_outputs(self) -> FlakeOutputs {
        match self {
            Self::UVal(v) => FlakeOutputs::Val(v),
            Self::UAttrset(v) => FlakeOutputs::Attrset(
                v.into_iter()
                    .map(|(k, v)| (k, v.into_flake_outputs()))
                    .collect(),
            ),
        }
    }
}

//! Flake URL types
//!
//! See <https://nixos.org/manual/nix/stable/command-ref/new-cli/nix3-flake.html#url-like-syntax>
use std::{
    fmt::{Display, Formatter},
    path::{Path, PathBuf},
    str::FromStr,
};

use serde::{Deserialize, Serialize};

/// A flake URL
///
/// See [syntax here](https://nixos.org/manual/nix/stable/command-ref/new-cli/nix3-flake.html#url-like-syntax).
///
/// Use `FromStr` to parse a string into a `FlakeUrl`. Or `From` or `Into` if
/// you know the URL is valid.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct FlakeUrl(pub String);

impl FlakeUrl {
    /// Provide real-world examples of flake URLs
    pub fn suggestions() -> Vec<FlakeUrl> {
        vec![
            "github:nammayatri/nammayatri".into(),
            "github:srid/emanote".into(),
            "github:srid/nixos-config".into(),
            "github:juspay/nix-browser".into(),
            "github:juspay/nix-dev-home".into(),
            // Commented out until we figure out rendering performance and/or
            // search filtering/limit.
            // "github:nixos/nixpkgs".into(),
        ]
    }

    /// Return the local path if the flake URL is a local path
    ///
    /// Applicable only if the flake URL uses the [Path-like
    /// syntax](https://nixos.org/manual/nix/stable/command-ref/new-cli/nix3-flake.html#path-like-syntax)
    pub fn as_local_path(&self) -> Option<&Path> {
        let s = self.0.strip_prefix("path:").unwrap_or(&self.0);
        if s.starts_with('.') || s.starts_with('/') {
            // Strip query (`?..`) and attrs (`#..`)
            let s = s.split('?').next().unwrap_or(s);
            let s = s.split('#').next().unwrap_or(s);
            Some(Path::new(s))
        } else {
            None
        }
    }

    /// Return `<url>#<root-attr>.default` if `<url>` is passed
    ///
    /// If `<url>#foo` is passed, return `<url>#<root-attr>.foo`.
    pub fn with_fully_qualified_root_attr(&self, root_attr: &str) -> Self {
        let (url, attr) = self.split_attr();
        let name = attr.get_name();
        FlakeUrl(format!("{}#{}.{}", url.0, root_attr, name))
    }

    /// Split the [FlakeAttr] out of the [FlakeUrl]
    pub fn split_attr(&self) -> (Self, FlakeAttr) {
        match self.0.split_once('#') {
            Some((url, attr)) => (FlakeUrl(url.to_string()), FlakeAttr(Some(attr.to_string()))),
            None => (self.clone(), FlakeAttr(None)),
        }
    }

    /// Return the flake URL with the given attribute
    pub fn with_attr(&self, attr: &str) -> Self {
        let (url, _) = self.split_attr();
        FlakeUrl(format!("{}#{}", url.0, attr))
    }

    /// Return the flake URL pointing to the sub-flake
    pub fn sub_flake_url(&self, dir: String) -> FlakeUrl {
        if dir == "." {
            self.clone()
        } else if let Some(path) = self.as_local_path() {
            // Local path; just join the dir
            let path_with_dir = path.join(dir);
            FlakeUrl(format!("path:{}", path_with_dir.display()))
        } else {
            // Non-path URL; append `dir` query parameter
            let mut url = self.0.clone();
            if url.contains('?') {
                url.push_str("&dir=");
            } else {
                url.push_str("?dir=");
            }
            url.push_str(&dir);
            FlakeUrl(url)
        }
    }
}

impl From<&str> for FlakeUrl {
    fn from(url: &str) -> Self {
        url.to_string().into()
    }
}

impl From<String> for FlakeUrl {
    fn from(url: String) -> Self {
        Self(url)
    }
}

impl From<PathBuf> for FlakeUrl {
    fn from(path: PathBuf) -> Self {
        FlakeUrl(format!("path:{}", path.display()))
    }
}

impl FromStr for FlakeUrl {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let s = s.trim();
        if s.is_empty() {
            Err("Empty string is not a valid Flake URL".to_string())
        } else {
            Ok(s.into())
        }
    }
}

impl Display for FlakeUrl {
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.0)
    }
}

/// The attribute output part of a [FlakeUrl]
///
/// Example: `foo` in `.#foo`.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct FlakeAttr(Option<String>);

impl FlakeAttr {
    /// Get the attribute name.
    ///
    /// If attribute exists, then return "default".
    pub fn get_name(&self) -> String {
        self.0.clone().unwrap_or_else(|| "default".to_string())
    }

    /// Whether an explicit attribute is set
    pub fn is_none(&self) -> bool {
        self.0.is_none()
    }

    /// Return nested attrs if the user specified one is separated by '.'
    pub fn as_list(&self) -> Vec<String> {
        self.0
            .clone()
            .map(|s| s.split('.').map(|s| s.to_string()).collect())
            .unwrap_or_default()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_flake_url_and_attr() {
        let url = FlakeUrl("github:srid/nixci".to_string());
        assert_eq!(url.split_attr(), (url.clone(), FlakeAttr(None)));
        assert_eq!(url.split_attr().1.as_list(), [] as [&str; 0]);

        let url = FlakeUrl("github:srid/nixci#extra-tests".to_string());
        assert_eq!(
            url.split_attr(),
            (
                FlakeUrl("github:srid/nixci".to_string()),
                FlakeAttr(Some("extra-tests".to_string()))
            )
        );
        assert_eq!(
            url.split_attr().1.as_list(),
            vec!["extra-tests".to_string()]
        );

        let url = FlakeUrl(".#foo.bar.qux".to_string());
        assert_eq!(
            url.split_attr(),
            (
                FlakeUrl(".".to_string()),
                FlakeAttr(Some("foo.bar.qux".to_string()))
            )
        );
        assert_eq!(
            url.split_attr().1.as_list(),
            vec!["foo".to_string(), "bar".to_string(), "qux".to_string()]
        )
    }

    #[test]
    fn test_as_local_flake() {
        let url = FlakeUrl("github:srid/nixci".to_string());
        assert_eq!(url.as_local_path(), None);

        let url = FlakeUrl(".".to_string());
        assert_eq!(url.as_local_path().map(|p| p.to_str().unwrap()), Some("."));

        let url = FlakeUrl("/foo".to_string());
        assert_eq!(url.as_local_path(), Some(std::path::Path::new("/foo")));

        let url = FlakeUrl("./foo?q=bar".to_string());
        assert_eq!(url.as_local_path(), Some(std::path::Path::new("./foo")));

        let url = FlakeUrl("./foo#attr".to_string());
        assert_eq!(url.as_local_path(), Some(std::path::Path::new("./foo")));

        let url = FlakeUrl("/foo?q=bar#attr".to_string());
        assert_eq!(url.as_local_path(), Some(std::path::Path::new("/foo")));

        let url = FlakeUrl("path:.".to_string());
        assert_eq!(url.as_local_path(), Some(std::path::Path::new(".")));

        let url = FlakeUrl("path:./foo".to_string());
        assert_eq!(url.as_local_path(), Some(std::path::Path::new("./foo")));

        let url = FlakeUrl("path:./foo?q=bar".to_string());
        assert_eq!(url.as_local_path(), Some(std::path::Path::new("./foo")));

        let url = FlakeUrl("path:./foo#attr".to_string());
        assert_eq!(url.as_local_path(), Some(std::path::Path::new("./foo")));

        let url = FlakeUrl("path:/foo?q=bar#attr".to_string());
        assert_eq!(url.as_local_path(), Some(std::path::Path::new("/foo")));
    }

    #[test]
    fn test_sub_flake_url() {
        // Path refs
        let url = FlakeUrl(".".to_string());
        assert_eq!(url.sub_flake_url(".".to_string()), url.clone());
        assert_eq!(
            url.sub_flake_url("sub".to_string()),
            FlakeUrl("path:./sub".to_string())
        );

        // URI refs
        let url = FlakeUrl("github:srid/nixci".to_string());
        assert_eq!(url.sub_flake_url(".".to_string()), url.clone());
        assert_eq!(
            url.sub_flake_url("dev".to_string()),
            FlakeUrl("github:srid/nixci?dir=dev".to_string())
        );
    }

    #[test]
    fn test_sub_flake_url_with_query() {
        let url = FlakeUrl("git+https://example.org/my/repo?ref=master".to_string());
        assert_eq!(url.sub_flake_url(".".to_string()), url.clone());
        assert_eq!(
            url.sub_flake_url("dev".to_string()),
            FlakeUrl("git+https://example.org/my/repo?ref=master&dir=dev".to_string())
        );
    }

    #[test]
    fn test_with_attr() {
        let url = FlakeUrl("github:srid/nixci".to_string());
        assert_eq!(
            url.with_attr("foo"),
            FlakeUrl("github:srid/nixci#foo".to_string())
        );

        let url: FlakeUrl = "github:srid/nixci#foo".parse().unwrap();
        assert_eq!(
            url.with_attr("bar"),
            FlakeUrl("github:srid/nixci#bar".to_string())
        );
    }
}

use crate::command::{CommandError, NixCmd, NixCmdError};

use super::url::FlakeUrl;

/// Run `nix eval <url> --json` and parse its JSON
///
/// If the flake does not output the given attribute, return the [Default]
/// value of `T`.
pub async fn nix_eval_attr_json<T>(
    cmd: &NixCmd,
    url: &FlakeUrl,
    default_if_missing: bool,
) -> Result<T, NixCmdError>
where
    T: Default + serde::de::DeserializeOwned,
{
    let result = cmd
        .run_with_args_expecting_json(&["eval", url.0.as_str(), "--json"])
        .await;
    match result {
        Err(err) if default_if_missing && error_is_missing_attribute(&err) => {
            // The 'nixci' flake output attr is missing. User wants the default config.
            Ok(T::default())
        }
        r => r,
    }
}

/// Check that [NixCmdError] is a missing attribute error
fn error_is_missing_attribute(err: &NixCmdError) -> bool {
    match err {
        NixCmdError::CmdError(CommandError::ProcessFailed { stderr, .. }) => {
            if let Some(stderr) = stderr {
                if stderr.contains("does not provide attribute") {
                    return true;
                }
            }
            false
        }
        _ => false,
    }
}

//! Nix system types
use std::{
    convert::Infallible,
    fmt::{Display, Formatter},
    str::FromStr,
};

use serde::{Deserialize, Serialize};
use serde_with::{DeserializeFromStr, SerializeDisplay};

/// The system for which a derivation will build
///
/// The enum includes the four standard systems, as well as a fallback to
/// capture the rest.
#[derive(
    Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord, SerializeDisplay, DeserializeFromStr,
)]
pub enum System {
    Darwin(Arch),
    Linux(Arch),
    Other(String),
}

/// CPU architecture in the system
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
pub enum Arch {
    Aarch64,
    X86_64,
}

impl FromStr for System {
    type Err = Infallible;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        Ok(Self::from(s))
    }
}

impl From<&str> for System {
    fn from(s: &str) -> Self {
        match s {
            "aarch64-linux" => Self::Linux(Arch::Aarch64),
            "x86_64-linux" => Self::Linux(Arch::X86_64),
            "x86_64-darwin" => Self::Darwin(Arch::X86_64),
            "aarch64-darwin" => Self::Darwin(Arch::Aarch64),
            _ => Self::Other(s.to_string()),
        }
    }
}

impl From<String> for System {
    fn from(s: String) -> Self {
        Self::from(s.as_str())
    }
}

impl AsRef<str> for System {
    fn as_ref(&self) -> &str {
        match self {
            System::Linux(Arch::Aarch64) => "aarch64-linux",
            System::Linux(Arch::X86_64) => "x86_64-linux",
            System::Darwin(Arch::X86_64) => "x86_64-darwin",
            System::Darwin(Arch::Aarch64) => "aarch64-darwin",
            System::Other(s) => s,
        }
    }
}

impl From<System> for String {
    fn from(s: System) -> Self {
        s.as_ref().to_string()
    }
}

impl Display for System {
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.as_ref())
    }
}

impl System {
    /// Return the human readable title for the Nix system
    pub fn human_readable(&self) -> String {
        match self {
            System::Linux(arch) => format!("Linux ({})", arch.human_readable()),
            System::Darwin(arch) => format!("macOS ({})", arch.human_readable()),
            System::Other(s) => s.clone(),
        }
    }
}

impl Arch {
    /// Return the human readable title for the CPU architecture
    pub fn human_readable(&self) -> &'static str {
        match self {
            Self::Aarch64 => "ARM",
            Self::X86_64 => "Intel",
        }
    }
}
